    public static function findCaseById(string $caseId): ?array
    {
        $all = static::getAllAssessmentCases();
        foreach ($all as $spec => $specData) {
            foreach ($specData['modules'] as $mod => $modData) {
                if (isset($modData['vignettes'][$caseId])) {
                    return $modData['vignettes'][$caseId];
                }
            }
        }
        return null;
    }

    public static function getTotalCasesCount(): int
    {
        $count = 0;
        foreach (static::getAllAssessmentCases() as $specData) {
            foreach ($specData['modules'] as $modData) {
                $count += count($modData['vignettes']);
            }
        }
        return $count;
    }

    public static function getTotalModulesCount(): int
    {
        $count = 0;
        foreach (static::getAllAssessmentCases() as $specData) {
            $count += count($specData['modules']);
        }
        return $count;
    }
}